:root {
  --ink: #1d1d1f;
  --muted: #5c5c66;
  --grid: #2b2b31;
  --paper: #f4f1ea;
  --cell: #fffdf8;
  --x: #1a4fa0;
  --o: #b3282d;
  --line-highlight: #d9a520;
  --fill-outline: #8f8a7e;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--paper);
  color: var(--ink);
}

.game {
  display: grid;
  gap: 1.25rem;
  justify-items: center;
  padding: 1.5rem;
}

h1 {
  margin: 0;
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.status {
  margin: 0;
  min-height: 1.6em;
  font-size: 1.15rem;
  color: var(--muted);
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 5rem);
  grid-template-rows: repeat(3, 5rem);
  gap: 0.35rem;
  padding: 0.35rem;
  background: var(--grid);
  border-radius: 0.6rem;
}

.cell {
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 0.3rem;
  background: var(--cell);
  font: 600 2.6rem/1 system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  cursor: pointer;
}

.cell[data-mark="X"] {
  color: var(--x);
}

.cell[data-mark="O"] {
  color: var(--o);
}

.cell[data-highlight="true"] {
  background: #fbf0cd;
  box-shadow: inset 0 0 0 0.28rem var(--line-highlight);
}

.board[data-outcome="fill"] {
  outline: 0.3rem solid var(--fill-outline);
  outline-offset: 0.4rem;
  filter: saturate(0.3);
}

.cell:disabled {
  cursor: default;
}

.new-game {
  padding: 0.55rem 1.2rem;
  border: 0;
  border-radius: 0.4rem;
  background: var(--grid);
  color: var(--cell);
  font: 600 1rem/1 system-ui, -apple-system, "Segoe UI", sans-serif;
  cursor: pointer;
}
